import {readFile,writeFile} from 'node:fs/promises';
const root='output/revisao-integral-20261119',j=JSON.parse(await readFile(root+'/velocidade-final-v2/resultados.json','utf8'));
const fontes={Laudos:['listar_laudos'],Agenda:['consultar_produtividade','pagina_servicos'],Contatos:['consultar_oportunidades'],'Relatórios':['consultar_relatorio_financeiro','consultar_relatorios_servicos'],Garantia:['consultar_qualidade','consultar_relatorios_servicos'],'Histórico':['consultar_historico_gestao'],Site:['administrar_site']};
function etapas(r){
 const acesso=r.recursos.find(x=>x.nome.endsWith('/consultar_meu_acesso')),rpc=r.recursos.find(x=>fontes[r.nome]?.some(n=>x.nome.endsWith('/'+n)));
 return {totalS:r.segundos,acessoS:acesso?acesso.duracao/1000:null,ateInicioConsultaS:rpc?rpc.inicio/1000:null,entreAcessoEConsultaS:rpc&&acesso?(rpc.inicio-acesso.inicio-acesso.duracao)/1000:null,consultaS:rpc?rpc.duracao/1000:null,aposRespostaS:rpc?r.segundos-(rpc.inicio+rpc.duracao)/1000:null,tarefasLongasS:r.longas.reduce((s,x)=>s+x.duracao,0)/1000,quantidadeAssets:r.recursos.filter(x=>x.nome.includes('/assets/')).length};
}
const pares=[];for(const d of j.resultados.filter(r=>r.fase==='depois')){const a=j.resultados.find(r=>r.fase==='antes'&&r.nome===d.nome&&r.perfil===d.perfil&&r.mobile===d.mobile);if(a)pares.push({perfil:d.perfil,dispositivo:d.mobile?'celular':'desktop',modulo:d.nome,deltaS:d.segundos-a.segundos,antes:etapas(a),depois:etapas(d)})}
const falhasHttp={};for(const r of j.rede)if(r.status>=400){const k=r.rpc+' · '+r.status;falhasHttp[k]=(falhasHttp[k]||0)+1}
const saida={metodo:'Decomposição pelo Resource Timing do navegador e Long Tasks. Consulta inclui proxy, rede e servidor: não é tempo isolado de SQL. Intervalo entre acesso e consulta inclui carregamento/renderização do frontend. O tempo depois da resposta inclui a checagem/pintura no navegador. Não soma medianas para representar um tempo total.',amostras:j.resultados.length,pares:pares.length,falhasDeCenario:j.falhas,falhasHttp,maisLentasDepois:pares.toSorted((a,b)=>b.depois.totalS-a.depois.totalS).slice(0,12),maioresAumentos:pares.toSorted((a,b)=>b.deltaS-a.deltaS).slice(0,12),comparacoes:pares};
await writeFile(root+'/diagnostico-tempos.json',JSON.stringify(saida,null,2));
const esc=s=>'"'+String(s??'').replaceAll('"','""')+'"';
await writeFile(root+'/tempos-por-subsistema.csv','\ufeff'+[['Perfil','Dispositivo','Módulo','Antes (s)','Depois (s)','Diferença (s)','Consulta antes (s)','Consulta depois (s)','Espera após acesso antes (s)','Espera após acesso depois (s)'],...pares.map(p=>[p.perfil,p.dispositivo,p.modulo,p.antes.totalS,p.depois.totalS,p.deltaS,p.antes.consultaS,p.depois.consultaS,p.antes.entreAcessoEConsultaS,p.depois.entreAcessoEConsultaS])].map(r=>r.map(esc).join(';')).join('\r\n'));
console.log(JSON.stringify({amostras:saida.amostras,pares:pares.length,falhasHttp,maisLentasDepois:saida.maisLentasDepois.slice(0,3),maioresAumentos:saida.maioresAumentos.slice(0,3)}));
